def solve(inputs: dict) -> float:
    n = inputs['n']
    k = inputs['k']

    # Josephus problem: find survivor position
    # n people in circle, eliminate every k-th person
    # Returns 0-indexed position, need to convert to 1-indexed

    def josephus(n, k):
        # Use simulation for correctness
        people = list(range(1, n + 1))  # 1-indexed positions
        idx = 0

        while len(people) > 1:
            # Move k-1 positions and remove (since we count the current person as 1)
            idx = (idx + k - 1) % len(people)
            people.pop(idx)
            # After removal, idx points to next person naturally
            # unless we're at the end, then wrap to 0
            if idx >= len(people) and len(people) > 0:
                idx = 0

        return float(people[0])

    return josephus(n, k)

